{
  "name": "wlan_rx_desc_process",
  "confidence": "medium",
  "docstring": "Drains a WLAN RX descriptor list, updates buffer status words, skips invalid zero-length entries, and queues a small host-visible RX event/message when valid descriptors require reporting.",
  "subsystem": "wlan",
  "var_renames": {
    "a2": "rx_desc_list",
    "v2": "mode_state_pp",
    "v5": "desc",
    "v6": "buffer_status_ptr",
    "v8": "buffer_status",
    "v9": "signed_event_value",
    "v10": "mode_state",
    "v11": "host_event_payload",
    "v12": "msg_desc_tmp",
    "v13": "masked_event_value",
    "v14": "msg_desc",
    "v15": "event_counter_ptr",
    "v16": "event_counter",
    "v17": "host_table_entry_offset",
    "v18": "host_event_table_pptr",
    "v19": "host_event_table_base",
    "v20": "host_table_control",
    "v21": "stats_or_global_status"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "RX descriptor uint16 length/valid field at desc offset 4; zero indicates no event/frame to process"
    },
    {
      "offset": 24,
      "meaning": "RX descriptor word v5[6], likely error/invalid flag or buffer count"
    },
    {
      "offset": 32,
      "meaning": "RX descriptor word v5[8], pointer to buffer status/control word"
    },
    {
      "offset": 40,
      "meaning": "RX descriptor word v5[10], signed timestamp/RSSI/event value used for host reporting"
    },
    {
      "offset": 0,
      "meaning": "host event payload byte type, set to 8"
    },
    {
      "offset": 2,
      "meaning": "host event payload uint16 total length, set to 18 bytes"
    },
    {
      "offset": 4,
      "meaning": "host event payload field containing low nibble of RX buffer status/control word"
    },
    {
      "offset": 8,
      "meaning": "host event payload field containing masked 30-bit signed RX event/timestamp value"
    },
    {
      "offset": 4,
      "meaning": "host message descriptor field v14[1], set to host table entry address"
    },
    {
      "offset": 8,
      "meaning": "host message descriptor field v14[2], set to 12, likely length/type/parameter"
    },
    {
      "offset": 14,
      "meaning": "host message descriptor byte at msg_desc offset 14, likely valid/owner flag"
    },
    {
      "offset": 0,
      "meaning": "host event table entry control word at host_event_table_base offset, ORed with 0x400000C"
    },
    {
      "offset": 4,
      "meaning": "host event table entry payload pointer at host_event_table_base + 4"
    }
  ]
}
